SELECT rowid AS history_rowid, * FROM transactions INDEXED BY idx_transactions_date
         WHERE 1 = 1 
         ORDER BY date DESC, created_at DESC, rowid DESC LIMIT ?;

SELECT rowid AS history_rowid, * FROM transactions INDEXED BY idx_transactions_date
         WHERE 1 = 1 
         ORDER BY date DESC, created_at DESC, rowid DESC LIMIT ?;

SELECT rowid AS history_rowid, id, date, created_at, merchant_name, description, notes FROM transactions INDEXED BY idx_transactions_date
         WHERE 1 = 1 AND ((instr(lower(merchant_name), ?) > 0 OR merchant_name GLOB '*[^ -~]*' OR instr(merchant_name, char(0)) > 0) OR (instr(lower(description), ?) > 0 OR description GLOB '*[^ -~]*' OR instr(description, char(0)) > 0) OR (instr(lower(notes), ?) > 0 OR notes GLOB '*[^ -~]*' OR instr(notes, char(0)) > 0)) 
         ORDER BY date DESC, created_at DESC, rowid DESC LIMIT ?;

